/// <summary>
///    The <c>METPurchaseOrderConfirmedBusinessEventContract</c> class extends <c>BusinessEventsContract</c> to provide data contract for purchase order confirmed business event.
/// </summary>
[DataContract]
public final class METPurchaseOrderConfirmedBusinessEventContract extends BusinessEventsContract
{
    private LegalEntityDataAreaId legalEntity;             
    private PurchaseOrderId purchaseJournal;
    private str purchaseType;
    private TransDate purchaseOrderDate;
    private PurchIdBase purchaseOrderNumber;    
    private VendCurrencyCode transactionCurrency;
    private AmountCur transactionCurrencyAmount;
    private VendAccount vendorAccount;
    private METMultiSelectStringValue poChngSubMode;
    private METMultiSelectStringValue poSubMode;

}

